  return { tree, project, comparison: comparison(root, project, pending, history, tree), ready: pending, history: branches,
    dirty: !!git(root, ['status', '--porcelain']).trim(),
    checks: [...checks.values()].sort((a, b) => b.recordedAt.localeCompare(a.recordedAt)).map(r => ({ ...r, current: equivalents.has(r.tree) })) };
}

export interface CheckResult {
  id: string; tree: string; method: string; outcome: 'pass' | 'fail' | 'inconclusive';
  recordedAt: string; environment: string; evidence: string;
  tests: { id: string; outcome: 'pass' | 'fail' | 'inconclusive' }[];
}
export interface ReviewInput {
  reviewer: string; summary: string;
  examined: { id: string; outcome: 'revised' | 'unchanged'; reason: string }[];
  unresolved: string[]; resultIds: string[];
}
export interface Review extends Omit<ReviewInput, 'resultIds'> {
  id: string; base: string; contentTree: string; recordedAt: string; results: CheckResult[];
}
export interface Ready { id: string; base: string; contentTree: string; finalTree: string; paths: string[]; reviewPath: string; createdAt: string }

const bindings = new Map<string, boolean>();
/** The final tree differs from reviewed content only by its newly added review. */
export function matchesReviewContent(root: string, tree: string, path: string, review: Review): boolean {
  try { if (!hash(tree)) tree = revision(root, tree); } catch { return false; }
  const key = JSON.stringify([root, tree, path, review.base, review.contentTree]);
  const cached = bindings.get(key);
  if (cached !== undefined) return cached;
  try {
    const added = !git(root, ['ls-tree', review.base, '--', path]).trim() && !!git(root, ['ls-tree', tree, '--', path]).trim();
    const matches = added && treeWithoutPath(root, tree, path) === review.contentTree;
    if (bindings.size >= 256) bindings.delete(bindings.keys().next().value!);
    bindings.set(key, matches);
    return matches;
  } catch { return false; }
}
